import{_ as i,o as s,c as t,a2 as e}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"속도 제한","description":"","frontmatter":{},"headers":[],"relativePath":"ko/advanced/ratelimit.md","filePath":"ko/advanced/ratelimit.md","lastUpdated":1784903584000}'),n={name:"ko/advanced/ratelimit.md"};function l(o,a,r,h,d,p){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="속도-제한" tabindex="-1">속도 제한 <a class="header-anchor" href="#속도-제한" aria-label="Permalink to &quot;속도 제한&quot;">​</a></h1><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>swag2mcp에는 LLM이 동일한 API 엔드포인트를 너무 자주 호출하는 것을 방지하는 내장 속도 제한기가 있습니다. 실수로 인한 중복 호출을 방지하고 API 속도 제한을 준수합니다.</p><h2 id="작동-방식" tabindex="-1">작동 방식 <a class="header-anchor" href="#작동-방식" aria-label="Permalink to &quot;작동 방식&quot;">​</a></h2><p>각 엔드포인트에는 쿨다운 기간이 있습니다. LLM이 쿨다운 내에 동일한 엔드포인트를 다시 호출하려고 하면 구조화된 오류와 함께 거부됩니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>t=0s  → invoke(endpoint) → 실행</span></span>
<span class="line"><span>t=2s  → invoke(endpoint) → rate_limit 오류로 거부</span></span>
<span class="line"><span>t=12s → invoke(endpoint) → 실행 (쿨다운 경과)</span></span></code></pre></div><h3 id="기본-동작" tabindex="-1">기본 동작 <a class="header-anchor" href="#기본-동작" aria-label="Permalink to &quot;기본 동작&quot;">​</a></h3><ul><li><strong>쿨다운:</strong> 엔드포인트당 10초</li><li><strong>범위:</strong> 엔드포인트별 — 엔드포인트 A 호출이 엔드포인트 B에 영향을 주지 않음</li><li><strong>오류 응답:</strong> LLM은 코드 <code>rate_limit</code>와 대기 시간을 알리는 메시지가 포함된 <code>LLMError</code>를 받습니다</li><li><strong>초기화:</strong> 해당 엔드포인트에서 10초 동안 활동이 없으면 초기화</li></ul><h3 id="오류-형식" tabindex="-1">오류 형식 <a class="header-anchor" href="#오류-형식" aria-label="Permalink to &quot;오류 형식&quot;">​</a></h3><p>속도 제한 시 LLM이 받는 응답:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rate_limit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;endpoint </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">abc123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">에 대한 속도 제한 초과: 8초 후에 다시 시도하세요&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;hint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;쿨다운 기간이 만료될 때까지 기다린 후 엔드포인트를 다시 호출하세요. 그동안 호출할 수 있는 다른 엔드포인트를 찾으려면 검색 도구를 사용하세요.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>LLM은 이 정보를 사용하여 대기 후 재시도하거나 다른 엔드포인트로 전환할 수 있습니다.</p><h3 id="존재-이유" tabindex="-1">존재 이유 <a class="header-anchor" href="#존재-이유" aria-label="Permalink to &quot;존재 이유&quot;">​</a></h3><ul><li><strong>실수로 인한 중복 호출 방지</strong> — LLM이 동일한 엔드포인트를 빠르게 연속해서 여러 번 호출할 수 있음</li><li><strong>API 속도 제한 보호</strong> — 많은 API에 자체 속도 제한이 있으며, 이를 초과하면 오류가 발생함</li><li><strong>리소스 절약</strong> — 불필요한 네트워크 트래픽 감소</li></ul><h2 id="설정" tabindex="-1">설정 <a class="header-anchor" href="#설정" aria-label="Permalink to &quot;설정&quot;">​</a></h2><p>속도 제한기를 비활성화하거나 쿨다운 간격을 변경할 수 있습니다:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 속도 제한기 완전 비활성화</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable_ratelimiter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 커스텀 쿨다운 간격</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rate_limit_interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">30s</span></span></code></pre></div><h3 id="disable-ratelimiter" tabindex="-1">disable_ratelimiter <a class="header-anchor" href="#disable-ratelimiter" aria-label="Permalink to &quot;disable_ratelimiter&quot;">​</a></h3><ul><li><strong>타입:</strong> <code>bool</code></li><li><strong>기본값:</strong> <code>false</code></li><li><strong>효과:</strong> <code>true</code>일 때 엔드포인트별 속도 제한기가 비활성화됩니다. LLM이 대기 없이 동일한 엔드포인트를 반복해서 호출할 수 있습니다.</li><li><strong>활성화 시기:</strong> 테스트, 디버깅 또는 동일한 엔드포인트를 빠르게 연속해서 여러 번 호출해야 할 때.</li><li><strong>비활성화 유지(권장):</strong> 프로덕션. 속도 제한기는 실수로 인한 남용을 방지합니다.</li></ul><h3 id="rate-limit-interval" tabindex="-1">rate_limit_interval <a class="header-anchor" href="#rate-limit-interval" aria-label="Permalink to &quot;rate_limit_interval&quot;">​</a></h3><ul><li><strong>타입:</strong> duration (Go 형식: <code>10s</code>, <code>30s</code>, <code>1m</code>)</li><li><strong>기본값:</strong> <code>10s</code></li><li><strong>효과:</strong> 동일한 엔드포인트 호출 간 LLM이 대기해야 하는 시간을 설정합니다.</li><li><strong>증가 시기:</strong> 엄격한 속도 제한이 있는 API(예: 분당 10회 요청).</li><li><strong>감소 시기:</strong> 부하를 제어할 수 있는 내부 API.</li><li><strong>예시:</strong> <code>5s</code>, <code>30s</code>, <code>1m</code>, <code>2m</code></li></ul><h2 id="중요-참고-사항" tabindex="-1">중요 참고 사항 <a class="header-anchor" href="#중요-참고-사항" aria-label="Permalink to &quot;중요 참고 사항&quot;">​</a></h2><ul><li><strong>엔드포인트별 추적</strong> — 각 엔드포인트는 독립적으로 추적됩니다. 하나의 엔드포인트를 호출해도 다른 엔드포인트에 영향을 주지 않습니다.</li><li><strong>LLM에 오류 반환</strong> — 쿨다운 내의 두 번째 호출은 <code>rate_limit</code> 오류와 함께 거부됩니다. LLM은 쿨다운 시간을 받고 대기 후 재시도할 수 있습니다.</li><li><strong>정리 불필요</strong> — 속도 제한기는 엔드포인트를 자동으로 추적하며 유지보수가 필요하지 않습니다.</li></ul>`,23)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
